const Home = () => {
    const [blogs, setBlogs] = useState([
        { id: 1, title: "Wut", body: "Lorem ipsum wtvr", author: "Mario" },
        { id: 2, title: "Why", body: "Another blog body", author: "Luigi" }
    ]);
    return ( 
        <div className="home">
            <h2>HomePage</h2>

        </div>
     );
}
 
export default Home;
